import pandas as pd

df = pd.DataFrame({
    "square_feet": [900, 1200, 1500, 1800, 2100, 2400],
    "price": [300000, 340000, 250000, 280000, 380000, 420000],
    "location": ["city", "city", "suburb", "suburb", "city", "city"],
})

for loc, group in df.groupby("location"):
    print(loc)
    print(group[["square_feet", "price"]].corr())
